verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const strip=(s)=>s.replace(/^\s*--.*$/gm," ")
const migs=fs.readdirSync("supabase/migrations").filter((f)=>f.endsWith(".sql")).sort().map((f)=>strip(fs.readFileSync("supabase/migrations/"+f,"utf8"))).join("\n")
const acts=rd("app/(main)/admin/library/actions.ts")
const page=rd("app/(main)/admin/library/page.tsx")
if(acts===null||page===null)process.exit(79)
if(!/[\x22\x27]library-private[\x22\x27]\s*,\s*[\x22\x27]library-private[\x22\x27]\s*,\s*false/i.test(migs))fail("no migration creates a private Loom bucket, so every Loom object is public and Protected is a word on a row")
const urls=rd("lib/library/asset-urls.ts")
if(urls===null||!/export async function signedLibraryAssetUrl\(/.test(urls))fail("nothing mints a signed URL for a Loom asset, so a private object could not be shown to the operator who owns it")
if(!/createSignedUrl/.test(urls))fail("signedLibraryAssetUrl signs nothing")
const pi=acts.indexOf("export async function protectLibraryAsset(")
if(pi<0)fail("there is no protect action, so an asset cannot be moved into the private bucket")
if(!/recordVersion\(/.test(acts.slice(pi,acts.indexOf("\n}",pi))))fail("protecting an asset records no version first, so the move cannot be rolled back like every other edit")
if(!/signedLibraryAssetUrl\(|proofLibraryAssetUrl\(/.test(page))fail("the Studio page never mints a signed URL, so a protected asset shows as a broken image to the person who protected it")
console.log("ok")'
